use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn all_ones(vec: Seq<i8>, n: nat) -> bool {
    forall|i: int| 0 <= i < n ==> vec[i] == 1
}

fn ones(n: usize) -> (result: Vec<i8>)
    ensures
        result.len() == n,
        forall|i: int| 0 <= i < n ==> result[i] == 1,
        forall|i: int, j: int| 0 <= i < n && 0 <= j < n ==> result[i] == result[j],
        forall|i: int| 0 <= i < n ==> result[i] > 0,
{
    let mut v: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    
    while i < n
        invariant
            0 <= i <= n,
            v.len() == i,
            forall|k: int| 0 <= k < i ==> v[k] == 1,
        decreases n - i,
    {
        v.push(1);
        i = i + 1;
    }
    
    // Prove the additional properties
    proof {
        assert forall|i: int, j: int| 0 <= i < n && 0 <= j < n implies v@[i] == v@[j] by {
            assert(v@[i] == 1);
            assert(v@[j] == 1);
        };
        
        assert forall|i: int| 0 <= i < n implies v@[i] > 0 by {
            assert(v@[i] == 1);
        };
    }
    
    v
}

} // verus!

